window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-45d637c65e5bb451"]={"versions": [{"id": "FIG-45d637c65e5bb451", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Signallaufdiagramm zur Einbindung gemultiplexter Sensoren in AUTOSAR Classic. Das Diagramm gliedert sich horizontal in Software- und Hardware-Ebene (getrennt durch eine gestrichelte Linie) sowie vertikal in die Schichten AUTOSAR SW-C, ECU Abstraction, Microcontroller Abstraction Layer (MCAL), On-Chip-Mikrocontroller-Hardware (µC), externe Komponenten auf dem Steuergerät (Components on ECU) und externe Sensoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>SW-C</strong>: AUTOSAR-Software-Komponente zur Verarbeitung des ausgewählten Sensorsignals.\n</li><li><strong>ECU Abstraction</strong>: Abstraktionsschicht zur Koordinierung der Adressauswahl und Bereitstellung des digitalisierten Sensorwerts.\n</li><li><strong>DIO-Drv</strong>: Digital I/O Driver im MCAL zur Ansteuerung digitaler Ausgangskanäle.\n</li><li><strong>ADC-Drv</strong>: Analog-to-Digital Converter Driver im MCAL zur Erfassung des gewandelten Werts.\n</li><li><strong>Digital-Outs (as Address)</strong>: Mikrocontroller-Hardware-Pins zur Ausgabe des Adressauswahlsignals.\n</li><li><strong>ADC</strong>: On-Chip Analog-to-Digital Converter zur Signalwandlung.\n</li><li><strong>Multiplex</strong>: Hardware-Multiplexer auf dem Steuergerät zur Kanalauswahl aus mehreren Sensoren.\n</li><li><strong>Sensoren</strong>: Mehrere analoge Sensorquellen am Eingang des Multiplexers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Adressauswahl (Address Selection, rot gestrichelt)</strong>: Die ECU Abstraction initiiert die Kanalumschaltung über den DIO-Treiber (<code>DIO-Drv</code>), der über digitale Ausgänge (<code>Digital-Outs (as Address)</code>) die Steuerleitungen des Multiplexers schaltet.\n</li><li><strong>Signalübertragung (Targeted Signal Flow, schwarze Pfeile)</strong>: Das analoge Signal des adressierten Sensors wird über den Multiplexer an den ADC des Mikrocontrollers durchgeschaltet, dort digitalisiert und über den ADC-Treiber (<code>ADC-Drv</code>) an die ECU Abstraction und weiter an die Ziel-SW-C übertragen.\n</li><li>Nicht ausgewählte Sensorsignale (graue Pfeile) werden am Multiplexer verworfen bzw. erst in nachfolgenden Multiplex-Schritten bedient.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Zusammenspiel zwischen Steuerungsfluss (DIO) und Messsignalfluss (ADC) bei der Erfassung mehrerer Sensoren über reduzierte Wandlerkanäle. Entwickler von ECU-Abstraktionsmodulen und Sensor-Treibern müssen das korrekte Einschwingverhalten und Timing zwischen Adressierung via DIO und Abtastung via ADC berücksichtigen, um Übersprechen und Fehlmessungen an gemultiplexten Kanälen zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cdf309b89265bf53", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Signallaufdiagramm zur Einbindung gemultiplexter Sensoren in AUTOSAR Classic. Das Diagramm gliedert sich horizontal in Software- und Hardware-Ebene (getrennt durch eine gestrichelte Linie) sowie vertikal in die Schichten AUTOSAR SW-C, ECU Abstraction, Microcontroller Abstraction Layer (MCAL), On-Chip-Mikrocontroller-Hardware (µC), externe Komponenten auf dem Steuergerät (Components on ECU) und externe Sensoren.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>SW-C</strong>: AUTOSAR-Software-Komponente zur Verarbeitung des ausgewählten Sensorsignals.\n</li><li><strong>ECU Abstraction</strong>: Abstraktionsschicht zur Koordinierung der Adressauswahl und Bereitstellung des digitalisierten Sensorwerts.\n</li><li><strong>DIO-Drv</strong>: Digital I/O Driver im MCAL zur Ansteuerung digitaler Ausgangskanäle.\n</li><li><strong>ADC-Drv</strong>: Analog-to-Digital Converter Driver im MCAL zur Erfassung des gewandelten Werts.\n</li><li><strong>Digital-Outs (as Address)</strong>: Mikrocontroller-Hardware-Pins zur Ausgabe des Adressauswahlsignals.\n</li><li><strong>ADC</strong>: On-Chip Analog-to-Digital Converter zur Signalwandlung.\n</li><li><strong>Multiplex</strong>: Hardware-Multiplexer auf dem Steuergerät zur Kanalauswahl aus mehreren Sensoren.\n</li><li><strong>Sensoren</strong>: Mehrere analoge Sensorquellen am Eingang des Multiplexers.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Adressauswahl (Address Selection, rot gestrichelt)</strong>: Die ECU Abstraction initiiert die Kanalumschaltung über den DIO-Treiber (<code>DIO-Drv</code>), der über digitale Ausgänge (<code>Digital-Outs (as Address)</code>) die Steuerleitungen des Multiplexers schaltet.\n</li><li><strong>Signalübertragung (Targeted Signal Flow, schwarze Pfeile)</strong>: Das analoge Signal des adressierten Sensors wird über den Multiplexer an den ADC des Mikrocontrollers durchgeschaltet, dort digitalisiert und über den ADC-Treiber (<code>ADC-Drv</code>) an die ECU Abstraction und weiter an die Ziel-SW-C übertragen.\n</li><li>Nicht ausgewählte Sensorsignale (graue Pfeile) werden am Multiplexer verworfen bzw. erst in nachfolgenden Multiplex-Schritten bedient.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht das Zusammenspiel zwischen Steuerungsfluss (DIO) und Messsignalfluss (ADC) bei der Erfassung mehrerer Sensoren über reduzierte Wandlerkanäle. Entwickler von ECU-Abstraktionsmodulen und Sensor-Treibern müssen das korrekte Einschwingverhalten und Timing zwischen Adressierung via DIO und Abtastung via ADC berücksichtigen, um Übersprechen und Fehlmessungen an gemultiplexten Kanälen zu vermeiden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-45d637c65e5bb451", "to": "FIG-cdf309b89265bf53", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
